let mySize;

// a shader variable
let theShader;

function preload() {
	theShader = createShader(vert, frag)
}

function setup() {
	// pixelDensity(5);
	mySize = max(windowWidth, windowHeight);
	// shaders require WEBGL mode to work
	createCanvas(windowWidth, windowHeight, WEBGL);
	noStroke();
}

function draw() {
	// shader() sets the active shader with our shader
	shader(theShader);

	theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("u_time", frameCount * 0.05);
	theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0) / height]);

	// rect gives us some geometry on the screen
	rect(0, 0, width, height);
}

